def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            i += 1
            field = []
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote
                        field.append('"')
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                            else:
                                return None
                        break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
            fields.append(''.join(field))
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    return None
                field.append(line[i])
                i += 1
            fields.append(''.join(field))
            if i < len(line) and line[i] == ',':
                i += 1

    return fields

